func (s *ManualCommitStrategy) carryForwardToNewShadowBranch(
	ctx context.Context,
	repo *git.Repository,
	state *SessionState,
	remainingFiles []string,
) {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	store := checkpoint.NewGitStore(repo)

	// Don't include metadata directory in carry-forward. The carry-forward branch
	// only needs to preserve file content for comparison - not the transcript.
	// Including the transcript would cause sessionHasNewContent to always return true
	// because CheckpointTranscriptStart is reset to 0 for carry-forward.
	result, err := store.WriteTemporary(ctx, checkpoint.WriteTemporaryOptions{
		SessionID:         state.SessionID,
		BaseCommit:        state.BaseCommit,
		WorktreeID:        state.WorktreeID,
		ModifiedFiles:     remainingFiles,
		MetadataDir:       "",
		MetadataDirAbs:    "",
		CommitMessage:     "carry forward: uncommitted session files",
		IsFirstCheckpoint: false,
	})
	if err != nil {
		logging.Warn(logCtx, "post-commit: carry-forward failed",
			slog.String("session_id", state.SessionID),
			slog.String("error", err.Error()),
		)
		return
	}
	if result.Skipped {
		logging.Debug(logCtx, "post-commit: carry-forward skipped (no changes)",
			slog.String("session_id", state.SessionID),
		)
		return
	}

	// Update state for the carry-forward checkpoint.
	// CheckpointTranscriptStart = 0 is intentional: each checkpoint is self-contained with
	// the full transcript. This trades storage efficiency for simplicity:
	// - Pro: Each checkpoint is independently readable without needing to stitch together
	//   multiple checkpoints to understand the session history
	// - Con: For long sessions with multiple partial commits, each checkpoint includes
	//   the full transcript, which could be large
	// An alternative would be incremental checkpoints (only new content since last condensation),
	// but this would complicate checkpoint retrieval and require careful tracking of dependencies.
	state.StepCount = 1
	state.CheckpointTranscriptStart = 0
	state.CheckpointTranscriptSize = 0
	state.LastCheckpointID = ""
	// NOTE: TurnCheckpointIDs is intentionally NOT cleared here. Those checkpoint
	// IDs from earlier in the turn still need finalization with the full transcript
	// when HandleTurnEnd runs at stop time.

	logging.Info(logCtx, "post-commit: carried forward remaining files",
		slog.String("session_id", state.SessionID),
		slog.Int("remaining_files", len(remainingFiles)),
	)
}

// If checkpoint was skipped due to deduplication (no changes), return early
if result.Skipped {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	logging.Info(logCtx, "checkpoint skipped (no changes)",
		slog.String("strategy", "manual-commit"),
		slog.String("checkpoint_type", "session"),
		slog.Int("checkpoint_count", state.StepCount),
		slog.String("shadow_branch", shadowBranchName),
	)
	return nil
}

// Update session state
_, updateStateSpan := perf.Start(ctx, "update_session_state")
state.StepCount++

// Note: LastCheckpointID is intentionally NOT cleared here.
// It is set during condensation and used by handleAmendCommitMsg
// to restore checkpoint trailers on amend operations.

// Store the prompt attribution we calculated before saving
state.PromptAttributions = append(state.PromptAttributions, promptAttr)

// Track touched files (modified, new, and deleted)
state.FilesTouched = mergeFilesTouched(state.FilesTouched, step.ModifiedFiles, step.NewFiles, step.DeletedFiles)

// On first checkpoint, record the transcript identifier for this session
if state.StepCount == 1 {
	state.TranscriptIdentifierAtStart = step.StepTranscriptIdentifier
}

// Accumulate token usage
if step.TokenUsage != nil {
	state.TokenUsage = accumulateTokenUsage(state.TokenUsage, step.TokenUsage)
}

// Save updated state
if err := s.saveSessionState(ctx, state); err != nil {
	updateStateSpan.RecordError(err)
	updateStateSpan.End()

func filesWithRemainingAgentChanges(
	ctx context.Context,
	repo *git.Repository,
	shadowBranchName string,
	headCommit *object.Commit,
	filesTouched []string,
	committedFiles map[string]struct{},
	opts ...overlapOpts,
) []string {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	// Use pre-resolved trees if provided, otherwise resolve from repo.
	var o overlapOpts
	if len(opts) > 0 {
		o = opts[0]
	}

	commitTree := o.headTree
	if commitTree == nil {
		var err error
		commitTree, err = headCommit.Tree()
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: failed to get commit tree, falling back to file subtraction",
				slog.String("error", err.Error()),
			)
			return subtractFilesByName(ctx, filesTouched, committedFiles)
		}
	}

	shadowTree := o.shadowTree
	if shadowTree == nil {
		refName := plumbing.NewBranchReferenceName(shadowBranchName)
		shadowRef, err := repo.Reference(refName, true)
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: shadow branch not found, falling back to file subtraction",
				slog.String("branch", shadowBranchName),
				slog.String("error", err.Error()),
			)
			return subtractFilesByName(ctx, filesTouched, committedFiles)
		}

		shadowCommit, err := repo.CommitObject(shadowRef.Hash())
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: failed to get shadow commit, falling back to file subtraction",
				slog.String("error", err.Error()),
			)
			return subtractFilesByName(ctx, filesTouched, committedFiles)
		}

		shadowTree, err = shadowCommit.Tree()
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: failed to get shadow tree, falling back to file subtraction",
				slog.String("error", err.Error()),
			)
			return subtractFilesByName(ctx, filesTouched, committedFiles)
		}
	}

	// Get worktree root for working tree checks when committed content
	// differs from shadow (distinguishes replacement from partial staging).
	var worktreeRoot string
	if wt, wtErr := repo.Worktree(); wtErr == nil {
		worktreeRoot = wt.Filesystem.Root()
	}

	var remaining []string

	for _, filePath := range filesTouched {
		// Skip files absent from the shadow tree — nothing to carry forward.
		// This covers two cases:
		//  1. Phantom paths: transcript mentions files the agent never created
		//     (e.g. agent writes src/types.go then creates src/types/types.go).
		//  2. Agent deletions: file was deleted on disk, so buildTreeWithChanges
		//     excluded it from the shadow tree. Carrying it forward would be a
		//     no-op since there's no content on disk to snapshot.
		// Without this check, phantom paths cause infinite carry-forward loops.
		shadowFile, err := shadowTree.File(filePath)
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: file not in shadow tree, skipping",
				slog.String("file", filePath),
			)
			continue
		}

		// File wasn't committed at all — it has remaining changes
		if _, wasCommitted := committedFiles[filePath]; !wasCommitted {
			remaining = append(remaining, filePath)
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: file not committed, keeping",
				slog.String("file", filePath),
			)
			continue
		}

		commitFile, err := commitTree.File(filePath)
		if err != nil {
			// File not in commit tree (deleted?) - keep it if it's in shadow
			remaining = append(remaining, filePath)
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: file not in commit tree but in shadow, keeping",
				slog.String("file", filePath),
			)

